diff --git a/deploy/k8s/log-shipper.yaml b/deploy/k8s/log-shipper.yaml
new file mode 100644
index 0000000..a5f1a51
--- /dev/null
+++ b/deploy/k8s/log-shipper.yaml
@@ -0,0 +1,29 @@
+apiVersion: apps/v1
+kind: DaemonSet
+metadata:
+  name: log-shipper
+  namespace: logging
+spec:
+  selector:
+    matchLabels: { app: log-shipper }
+  template:
+    metadata:
+      labels: { app: log-shipper }
+    spec:
+      tolerations:
+        - { effect: NoSchedule, operator: Exists }
+      containers:
+        - name: log-shipper
+          image: registry.example.com/ops/shipper:3.4.1
+          env:
+            - { name: COLLECTOR_ENDPOINT, value: collector.logging:4317 }
+            - { name: LOG_DIR, value: /var/log/containers }
+          resources:
+            requests: { cpu: 100m, memory: 128Mi }
+            limits: { cpu: 500m, memory: 256Mi }
+          volumeMounts:
+            - { name: varlogcontainers, mountPath: /var/log/containers, readOnly: true }
+            - { name: varlogpods, mountPath: /var/log/pods, readOnly: true }
+      volumes:
+        - { name: varlogcontainers, hostPath: { path: /var/log/containers } }
+        - { name: varlogpods, hostPath: { path: /var/log/pods } }

