diff --git a/infra/dumps.tf b/infra/dumps.tf
new file mode 100644
index 0000000..6c4ba72
--- /dev/null
+++ b/infra/dumps.tf
@@ -0,0 +1,122 @@
+variable "backup_role_arn" {
+  description = "ARN of the IAM role permitted to read/write raw database dumps"
+  type        = string
+}
+
+data "aws_caller_identity" "current" {}
+
+resource "aws_s3_bucket" "db_dumps" {
+  bucket = "shop-db-dumps-${var.env}"
+}
+
+resource "aws_s3_bucket_public_access_block" "db_dumps" {
+  bucket = aws_s3_bucket.db_dumps.id
+
+  block_public_acls       = true
+  block_public_policy     = true
+  ignore_public_acls      = true
+  restrict_public_buckets = true
+}
+
+resource "aws_s3_bucket_versioning" "db_dumps" {
+  bucket = aws_s3_bucket.db_dumps.id
+
+  versioning_configuration {
+    status = "Enabled"
+  }
+}
+
+resource "aws_kms_key" "db_dumps" {
+  description             = "CMK for encrypting raw database dumps in shop-db-dumps-${var.env}"
+  enable_key_rotation     = true
+  deletion_window_in_days = 30
+
+  policy = jsonencode({
+    Version = "2012-10-17"
+    Statement = [
+      {
+        Sid       = "AllowKeyAdministration"
+        Effect    = "Allow"
+        Principal = { AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root" }
+        Action    = "kms:*"
+        Resource  = "*"
+      },
+      {
+        Sid    = "AllowBackupRoleUsage"
+        Effect = "Allow"
+        Principal = {
+          AWS = var.backup_role_arn
+        }
+        Action = [
+          "kms:Encrypt",
+          "kms:Decrypt",
+          "kms:ReEncrypt*",
+          "kms:GenerateDataKey*",
+          "kms:DescribeKey",
+        ]
+        Resource = "*"
+      },
+    ]
+  })
+}
+
+resource "aws_kms_alias" "db_dumps" {
+  name          = "alias/shop-db-dumps-${var.env}"
+  target_key_id = aws_kms_key.db_dumps.key_id
+}
+
+resource "aws_s3_bucket_server_side_encryption_configuration" "db_dumps" {
+  bucket = aws_s3_bucket.db_dumps.id
+
+  rule {
+    apply_server_side_encryption_by_default {
+      sse_algorithm     = "aws:kms"
+      kms_master_key_id = aws_kms_key.db_dumps.arn
+    }
+    bucket_key_enabled = true
+  }
+}
+
+resource "aws_s3_bucket_policy" "db_dumps" {
+  bucket = aws_s3_bucket.db_dumps.id
+
+  policy = jsonencode({
+    Version = "2012-10-17"
+    Statement = [
+      {
+        Sid       = "AllowBackupRoleReadWrite"
+        Effect    = "Allow"
+        Principal = { AWS = var.backup_role_arn }
+        Action    = ["s3:GetObject", "s3:PutObject"]
+        Resource  = "${aws_s3_bucket.db_dumps.arn}/*"
+      },
+      {
+        Sid       = "DenyReadWriteFromOtherPrincipals"
+        Effect    = "Deny"
+        Principal = "*"
+        Action    = ["s3:GetObject", "s3:PutObject"]
+        Resource  = "${aws_s3_bucket.db_dumps.arn}/*"
+        Condition = {
+          StringNotEquals = {
+            "aws:PrincipalArn" = var.backup_role_arn
+          }
+        }
+      },
+    ]
+  })
+}
+
+resource "aws_s3_bucket_lifecycle_configuration" "db_dumps" {
+  bucket = aws_s3_bucket.db_dumps.id
+
+  rule {
+    id     = "expire-after-35-days"
+    status = "Enabled"
+
+    filter {}
+
+    expiration {
+      days = 35
+    }
+  }
+}

