@@ -0,0 +1,151 @@
+# prevent_destroy blocks a plain revert-and-reapply. To tear this bucket down
+# intentionally: (1) remove the `lifecycle { prevent_destroy = true }` block
+# below and apply that change first, then (2) run `terraform destroy` (or a
+# targeted destroy) against the bucket. Removing both steps at once will not
+# self-service a rollback.
+resource "aws_s3_bucket" "db_dumps" {
+  bucket = "shop-db-dumps-${var.env}"
+
+  lifecycle {
+    prevent_destroy = true
+  }
+}
+
+resource "aws_s3_bucket_versioning" "db_dumps" {
+  bucket = aws_s3_bucket.db_dumps.id
+
+  versioning_configuration {
+    status = "Enabled"
+  }
+}
+
+resource "aws_s3_bucket_public_access_block" "db_dumps" {
+  bucket = aws_s3_bucket.db_dumps.id
+
+  block_public_acls       = true
+  block_public_policy     = true
+  ignore_public_acls      = true
+  restrict_public_buckets = true
+}
+
+resource "aws_s3_bucket_server_side_encryption_configuration" "db_dumps" {
+  bucket = aws_s3_bucket.db_dumps.id
+
+  rule {
+    apply_server_side_encryption_by_default {
+      sse_algorithm = "AES256"
+    }
+  }
+}
+
+resource "aws_s3_bucket_lifecycle_configuration" "db_dumps" {
+  bucket = aws_s3_bucket.db_dumps.id
+
+  rule {
+    id     = "expire-after-35-days"
+    status = "Enabled"
+
+    filter {}
+
+    expiration {
+      days = 35
+    }
+
+    abort_incomplete_multipart_upload {
+      days_after_initiation = 7
+    }
+  }
+}
+
+# Cross-region replica so a source-region outage or account compromise
+# doesn't take out the only copy of the dumps along with the primary.
+resource "aws_s3_bucket" "db_dumps_dr" {
+  provider = aws.dr
+  bucket   = "shop-db-dumps-${var.env}-dr"
+}
+
+resource "aws_s3_bucket_versioning" "db_dumps_dr" {
+  provider = aws.dr
+  bucket   = aws_s3_bucket.db_dumps_dr.id
+
+  versioning_configuration {
+    status = "Enabled"
+  }
+}
+
+resource "aws_s3_bucket_public_access_block" "db_dumps_dr" {
+  provider = aws.dr
+  bucket   = aws_s3_bucket.db_dumps_dr.id
+
+  block_public_acls       = true
+  block_public_policy     = true
+  ignore_public_acls      = true
+  restrict_public_buckets = true
+}
+
+resource "aws_s3_bucket_server_side_encryption_configuration" "db_dumps_dr" {
+  provider = aws.dr
+  bucket   = aws_s3_bucket.db_dumps_dr.id
+
+  rule {
+    apply_server_side_encryption_by_default {
+      sse_algorithm = "AES256"
+    }
+  }
+}
+
+data "aws_iam_policy_document" "db_dumps_replication_assume" {
+  statement {
+    actions = ["sts:AssumeRole"]
+
+    principals {
+      type        = "Service"
+      identifiers = ["s3.amazonaws.com"]
+    }
+  }
+}
+
+resource "aws_iam_role" "db_dumps_replication" {
+  name               = "shop-db-dumps-${var.env}-replication"
+  assume_role_policy = data.aws_iam_policy_document.db_dumps_replication_assume.json
+}
+
+data "aws_iam_policy_document" "db_dumps_replication" {
+  statement {
+    actions   = ["s3:GetReplicationConfiguration", "s3:ListBucket"]
+    resources = [aws_s3_bucket.db_dumps.arn]
+  }
+
+  statement {
+    actions   = ["s3:GetObjectVersionForReplication", "s3:GetObjectVersionAcl", "s3:GetObjectVersionTagging"]
+    resources = ["${aws_s3_bucket.db_dumps.arn}/*"]
+  }
+
+  statement {
+    actions   = ["s3:ReplicateObject", "s3:ReplicateDelete", "s3:ReplicateTags"]
+    resources = ["${aws_s3_bucket.db_dumps_dr.arn}/*"]
+  }
+}
+
+resource "aws_iam_role_policy" "db_dumps_replication" {
+  name   = "shop-db-dumps-${var.env}-replication"
+  role   = aws_iam_role.db_dumps_replication.id
+  policy = data.aws_iam_policy_document.db_dumps_replication.json
+}
+
+resource "aws_s3_bucket_replication_configuration" "db_dumps" {
+  bucket = aws_s3_bucket.db_dumps.id
+  role   = aws_iam_role.db_dumps_replication.arn
+
+  rule {
+    id     = "replicate-to-dr"
+    status = "Enabled"
+
+    destination {
+      bucket        = aws_s3_bucket.db_dumps_dr.arn
+      storage_class = "STANDARD_IA"
+    }
+  }
+
+  depends_on = [aws_s3_bucket_versioning.db_dumps, aws_s3_bucket_versioning.db_dumps_dr]
+}
